import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.ts";

const col = (m: any, c: number) => [m[4 * c], m[4 * c + 1], m[4 * c + 2]];
const close = (a: number[], b: number[], eps = 1e-6) => a.forEach((v, i) => expect(Math.abs(v - b[i]!)).toBeLessThan(eps));
const n = (v: number[]) => { const l = Math.hypot(...v); return v.map((x) => x / l); };

describe("chase camera", () => {
    it("starts upright", () => {
        const c = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        close(col(c.camera.worldMatrix, 1), [0, 1, 0]);
    });
    it("rolls to a tilted up, projected onto the view plane", () => {
        const c = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        c.bank({ x: 1, y: 0, z: 0 });
        close(col(c.camera.worldMatrix, 1), [1, 0, 0]);
        c.bank({ x: 1, y: 1, z: 5 }); // z component is dropped by the projection
        close(col(c.camera.worldMatrix, 1), n([1, 1, 0]));
        // still looking at the target
        close(col(c.camera.worldMatrix, 2), [0, 0, 1]);
    });
    it("keeps previous roll on exact parallel and antiparallel up", () => {
        const c = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        c.bank({ x: 1, y: 0, z: 0 });
        const before = col(c.camera.worldMatrix, 1);
        c.bank({ x: 0, y: 0, z: 1 });
        close(col(c.camera.worldMatrix, 1), before);
        c.bank({ x: 0, y: 0, z: -1 });
        close(col(c.camera.worldMatrix, 1), before);
        close(col(c.camera.worldMatrix, 2), [0, 0, 1]);
    });
    it("keeps previous roll on near-parallel up (float noise)", () => {
        const c = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        c.bank({ x: 0, y: 1, z: 0 });
        c.bank({ x: 1e-13, y: 0.0, z: 1 });
        close(col(c.camera.worldMatrix, 1), [0, 1, 0]);
    });
    it("works on an oblique view and keeps the picture up orthogonal to the line of sight", () => {
        const c = createChaseCamera({ x: 3, y: 4, z: -7 }, { x: -1, y: 2, z: 5 });
        const up = n([0.3, -0.8, 0.5]);
        c.bank({ x: up[0]!, y: up[1]!, z: up[2]! });
        const z = n([-4, -2, 12]);
        const y = col(c.camera.worldMatrix, 1);
        const dot = y[0]! * z[0]! + y[1]! * z[1]! + y[2]! * z[2]!;
        expect(Math.abs(dot)).toBeLessThan(1e-6);
        expect(Math.hypot(...y)).toBeCloseTo(1, 6);
        // picture up has positive dot with the requested up
        expect(y[0]! * up[0]! + y[1]! * up[1]! + y[2]! * up[2]!).toBeGreaterThan(0.9);
    });
    it("parallel to an oblique line of sight keeps the roll", () => {
        const c = createChaseCamera({ x: 3, y: 4, z: -7 }, { x: -1, y: 2, z: 5 });
        const up = n([0.3, -0.8, 0.5]);
        c.bank({ x: up[0]!, y: up[1]!, z: up[2]! });
        const before = col(c.camera.worldMatrix, 1);
        const z = n([-4, -2, 12]);
        c.bank({ x: -z[0]!, y: -z[1]!, z: -z[2]! });
        close(col(c.camera.worldMatrix, 1), before);
        c.bank({ x: z[0]!, y: z[1]!, z: z[2]! });
        close(col(c.camera.worldMatrix, 1), before);
    });
});
